const results = [];
const items = $input.all();

// Mock logic: group by operator
const operators = {};
const machines = {};

items.forEach(item => {
  const row = item.json;
  const op = row['Operador'] || 'Desconhecido';
  const machine = row['Máquina'] || 'Geral';

  if(!operators[op]) operators[op] = { name: op, totalIssues: 0, byMachine: {} };
  if(!machines[machine]) machines[machine] = { name: machine, totalIssues: 0 };

  // Assume issues are in columns starting with "Defeito"
  Object.keys(row).forEach(key => {
    if(key.includes('Defeito') && Number(row[key]) > 0) {
      const count = Number(row[key]);
      operators[op].totalIssues += count;
      machines[machine].totalIssues += count;
    }
  });
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    operators: Object.values(operators),
    machines: Object.values(machines),
    totalProcessed: items.length
  }
}];
